---@class BattleEntry
local BattleEntry = Class("BattleEntry")

function BattleEntry:__init()
    self._loadingUI = nil
end

function BattleEntry:__delete()
    self._loadingUI = nil
    self.controller = nil
end

function BattleEntry:Awake()
    UINavigationBarRoot.Instance:SetActive(false)
end


function BattleEntry:OnShow()
    --- @type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        UINavigationBarRoot.Instance:SetActive(false)
    end))
    return coWait
end


---SetLoadingUI
---设置加载进条的逻辑的逻辑
---@param loadingEnv table
function BattleEntry:SetLoadingUI(loadingEnv)
    self._loadingUI = loadingEnv
end

function BattleEntry:AsyncLoadingResources()
    BattleViewMgr:Start()
end

function BattleEntry:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xpcall(function ()
            KTool.SetRenderFeatureActiveByName(Constants.RenderFeatureNames.BLUR, false)
            BattleMgr = import('Game.Battle.Core.BattleMgr')
            BattleViewMgr = import('Game.BattleView.Core.BattleViewMgr')
        end, function(err)
            print(err)
            printError(tostring(err))
        end)

    end))
    return coWait
end

function BattleEntry:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xpcall(function ()
            self._loadingUI = nil
            UINavigationBarRoot.Instance:SetActive(true)
            if BattleViewMgr then
                BattleViewMgr:OnDestroy()
            end
            CS.UnityEngine.LightmapSettings.lightProbes = nil
            BattleViewMgr = nil
            self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要
        end, function (err)
            local nativeFXMgr = CS.Game.Native.ParticleManager.Instance
            nativeFXMgr:TearDown()
            printError(tostring(err))
        end)
    end))
    return coWait
end

return BattleEntry